local Profiles={};Profiles.__index=Profiles;local W={weapon_crowbar=1,weapon_pistol=1,weapon_smg1=1,weapon_shotgun=1};local C={Pistol=200,SMG1=120,Buckshot=32}
local function cp(v)if type(v)~="table"then return v end;local o={};for k,x in pairs(v)do o[cp(k)]=cp(x)end;return o end
local function ident(v)return type(v)=="string"and#v>0 and#v<=128 and v:match("^[%w][%w_.:%-]*$")end;local function pname(v)return type(v)=="string"and#v<=32 and v:match("^[%w_-]+$")end;local function int(v)return type(v)=="number"and v>=0 and v%1==0 and v<math.huge end
local function find(rows,p,n)for _,r in ipairs(rows)do if r.player_id==p and(n==nil or r.name==n)then return r end end end
local function norm(s)if type(s)~="table"or type(s.weapons)~="table"or#s.weapons<1 or#s.weapons>4 then return nil,"invalid_profile"end;local ws,seen,total={},{},{};for _,w in ipairs(s.weapons)do if type(w)~="table"or not W[w.class]or seen[w.class]then return nil,"invalid_weapon"end;seen[w.class]=1;local x={class=w.class};for _,k in ipairs({"primary","secondary"})do local a=w[k];if a then if type(a)~="table"or not C[a.type]or not int(a.amount)then return nil,"invalid_ammo"end;x[k]=cp(a);total[a.type]=(total[a.type]or 0)+a.amount end end;ws[#ws+1]=x end;local ammo={};for t,n in pairs(total)do if n>C[t]then return nil,"ammo_cap_exceeded"end;ammo[#ammo+1]={type=t,amount=n}end;table.sort(ws,function(a,b)return a.class<b.class end);table.sort(ammo,function(a,b)return a.type<b.type end);return{weapons=ws,ammo=ammo}end
local function encode(v)if type(v)~="table"then return type(v)..":"..tostring(v)end;local ks={};for k in pairs(v)do ks[#ks+1]=k end;table.sort(ks,function(a,b)return tostring(a)<tostring(b)end);local out={"{"};for _,k in ipairs(ks)do out[#out+1]=encode(k).."="..encode(v[k])..";"end;out[#out+1]="}";return table.concat(out)end
local function key(m,a)local out={m};for _,v in ipairs(a)do out[#out+1]=encode(v)end;return table.concat(out,"|")end
local function array(v)if type(v)~="table"then return false end;local n=0;for k in pairs(v)do if type(k)~="number"or k<1 or k%1~=0 then return false end;n=n+1 end;return n==#v end
local function fields(v,a)local n=0;for k in pairs(v)do if not a[k]then return false end;n=n+1 end;return n end
local function serial(v,seen)local t=type(v);if t=="nil"or t=="string"or t=="boolean"then return true end;if t=="number"then return v==v and v<math.huge and v>-math.huge end;if t~="table"then return false end;seen=seen or{};if seen[v]then return false end;seen[v]=true;for k,x in pairs(v)do if(type(k)~="string"and type(k)~="number")or not serial(k,seen)or not serial(x,seen)then return false end end;seen[v]=nil;return true end
function Profiles.new(o)o=o or{};local s=setmetatable({profile_rows={},choice_rows={},request_rows={},last_now=0,stopped=false},Profiles);local st=o.state;if st then if type(st)~="table"or st.schema_version~=1 or fields(st,{schema_version=1,last_now=1,profiles=1,choices=1,requests=1})~=5 or not int(st.last_now)and not(type(st.last_now)=="number"and st.last_now==st.last_now and st.last_now>=0 and st.last_now<math.huge)or not array(st.profiles)or not array(st.choices)or not array(st.requests)then return nil,"invalid_state"end;local ps,cs,rs,counts={},{},{},{};for _,r in ipairs(st.profiles)do local k=type(r)=="table"and tostring(r.player_id).."\0"..tostring(r.name)or"";if type(r)~="table"or fields(r,{player_id=1,name=1,revision=1,plan=1})~=4 or not ident(r.player_id)or not pname(r.name)or ps[k]or not int(r.revision)or r.revision<1 or type(r.plan)~="table"then return nil,"invalid_state"end;local normalized=norm({weapons=r.plan.weapons});if not normalized or encode(normalized)~=encode(r.plan)then return nil,"invalid_state"end;ps[k]=true;counts[r.player_id]=(counts[r.player_id]or 0)+1;if counts[r.player_id]>5 then return nil,"invalid_state"end end;for _,r in ipairs(st.choices)do if type(r)~="table"or fields(r,{player_id=1,name=1,revision=1})~=3 or not ident(r.player_id)or not pname(r.name)or cs[r.player_id]or not int(r.revision)or r.revision<1 or not ps[r.player_id.."\0"..r.name]then return nil,"invalid_state"end;cs[r.player_id]=true end;for _,r in ipairs(st.requests)do if type(r)~="table"or fields(r,{id=1,key=1,ok=1,code=1,data=1})~=5 or not ident(r.id)or rs[r.id]or type(r.key)~="string"or r.key==""or type(r.ok)~="boolean"or type(r.code)~="string"or r.code==""or type(r.data)~="table"or not serial(r.data)then return nil,"invalid_state"end;rs[r.id]=true end;s.profile_rows=cp(st.profiles);s.choice_rows=cp(st.choices);s.request_rows=cp(st.requests);s.last_now=st.last_now end;return s end
function Profiles:_old(r,m,a)if not ident(r)then return false,"invalid_request_id",{}end;local k=key(m,a);for _,x in ipairs(self.request_rows)do if x.id==r then if x.key~=k then return false,"request_conflict",{}end;return x.ok,x.code,cp(x.data)end end;return nil,k end
function Profiles:_remember(id,k,ok,c,d)self.request_rows[#self.request_rows+1]={id=id,key=k,ok=ok,code=c,data=cp(d or{})};return ok,c,cp(d or{})end
function Profiles:put(r,p,n,spec,rev)if self.stopped then return false,"shutdown",{}end;local old,k,d=self:_old(r,"put",{p,n,rev,spec and spec.weapons});if old~=nil then return old,k,d end;if not ident(p)or not pname(n)or not int(rev)or rev<1 then return self:_remember(r,k,false,"invalid_profile",{})end;local plan,e=norm(spec);if not plan then return self:_remember(r,k,false,e,{})end;local cur=find(self.profile_rows,p,n);if cur and rev<=cur.revision then return self:_remember(r,k,false,"stale_revision",{})end;local count=0;for _,x in ipairs(self.profile_rows)do if x.player_id==p then count=count+1 end end;if not cur and count>=5 then return self:_remember(r,k,false,"profile_limit",{})end;if cur then cur.revision=rev;cur.plan=plan else self.profile_rows[#self.profile_rows+1]={player_id=p,name=n,revision=rev,plan=plan}end;return self:_remember(r,k,true,"stored",{name=n,revision=rev})end
function Profiles:select(r,p,n,rev)if self.stopped then return false,"shutdown",{}end;local old,k,d=self:_old(r,"select",{p,n,rev});if old~=nil then return old,k,d end;if not ident(p)or not pname(n)or not int(rev)or rev<1 then return self:_remember(r,k,false,"invalid_profile",{})end;if not find(self.profile_rows,p,n)then return self:_remember(r,k,false,"not_found",{})end;local c=find(self.choice_rows,p);if c and rev<=c.revision then return self:_remember(r,k,false,"stale_revision",{})end;if c then c.name=n;c.revision=rev else self.choice_rows[#self.choice_rows+1]={player_id=p,name=n,revision=rev}end;return self:_remember(r,k,true,"selected",{name=n,revision=rev})end
function Profiles:get(p,n)local x=find(self.profile_rows,p,n);if not x then return nil,"not_found"end;return{revision=x.revision,plan=cp(x.plan)}end
function Profiles:preferred(p)local x=find(self.choice_rows,p);return x and x.name end
function Profiles:plan(p)local n=self:preferred(p);local x=n and find(self.profile_rows,p,n);if not x then return nil,"not_found"end;return cp(x.plan)end
function Profiles:disconnect(p,t)if type(t)=="number"and t>=0 and t>self.last_now then self.last_now=t end;return true,"retained",{player_id=p}end
function Profiles:save(t)if type(t)=="number"and t>=0 and t>self.last_now then self.last_now=t end;local p,c,r=cp(self.profile_rows),cp(self.choice_rows),cp(self.request_rows);table.sort(p,function(a,b)return a.player_id==b.player_id and a.name<b.name or a.player_id<b.player_id end);return{schema_version=1,last_now=self.last_now,profiles=p,choices=c,requests=r}end
function Profiles:shutdown()self.stopped=true;return true,"shutdown"end;return Profiles
